&lt;p&gt;&lt;span style=&quot;color: rgb(0, 0, 0);&quot;&gt;&lt;em&gt;&lt;img style=&quot;max-width: 100%;&quot; src=&quot;https://i.imgur.com/TH4zQxp.png&quot; alt=&quot;&quot; width=&quot;700&quot;&gt;&lt;/em&gt;&lt;/span&gt;&lt;/p&gt;
